#!/usr/bin/env python3
from __future__ import annotations

import datetime as dt
import ssl
from pathlib import Path
import sys

CERT_PATH = Path("/app/ssl/server.crt")


def fail(msg: str) -> None:
    print(msg, file=sys.stderr)
    raise SystemExit(1)


def main() -> None:
    if not CERT_PATH.exists():
        fail(f"Certificate not found: {CERT_PATH}")
    try:
        info = ssl._ssl._test_decode_cert(str(CERT_PATH))
    except Exception as exc:
        fail(f"Unable to load certificate: {exc}")

    subject = {}
    for rdn in info.get("subject", []):
        for key, value in rdn:
            subject[key] = value

    cn = subject.get("commonName")
    if not cn:
        fail("Common Name missing from certificate")

    not_after = info.get("notAfter")
    if not not_after:
        fail("Expiration date missing from certificate")

    try:
        exp = dt.datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z")
    except ValueError:
        try:
            exp = dt.datetime.strptime(not_after, "%b %d %H:%M:%S %Y GMT")
        except ValueError as exc:
            fail(f"Could not parse expiration date: {exc}")

    print(f"Common Name: {cn}")
    print(f"Expiration date: {exp.strftime('%Y-%m-%d')}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()
